import React, { useState, useEffect } from 'react';
import { createBooking } from '../utils/api';

function BookingForm({ slot, onBooked }) {
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [error, setError] = useState('');
  const [cost, setCost] = useState(0);

  useEffect(() => {
    if (slot && startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      if (start < end) {
        const durationMs = end - start;
        const durationHours = Math.ceil(durationMs / (1000 * 60 * 60));
        const calculatedCost = durationHours * slot.hourlyRate;
        setCost(calculatedCost);
      } else {
        setCost(0);
      }
    } else {
      setCost(0);
    }
  }, [startTime, endTime, slot]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!slot) {
      setError('Slot not loaded');
      return;
    }

    const now = new Date();
    const start = new Date(startTime);
    const end = new Date(endTime);

    if (!vehicleNumber) {
      setError('Vehicle number is required');
      return;
    }

    if (start >= end) {
      setError('Start time must be before end time');
      return;
    }

    if (start < now) {
      setError('Start time cannot be in the past');
      return;
    }

    try {
      const userId = 1; // Adjust if needed
      const response = await createBooking({
        vehicleNumber,
        startTime,
        endTime,
      }, userId, slot.id);
      onBooked(response);
    } catch (err) {
      const msg = err?.response?.data?.message || 'Booking failed!';
      setError(msg);
    }
  };

  if (!slot) {
    return <p>Loading slot details...</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>Book Slot {slot?.slotNumber}</h2>

      <div>
        <label>Vehicle Number:</label>
        <input
          data-testid="vehicle-input"
          type="text"
          value={vehicleNumber}
          onChange={(e) => setVehicleNumber(e.target.value)}
        />
      </div>

      <div>
        <label>Start Time:</label>
        <input
          data-testid="start-time-input"
          type="datetime-local"
          value={startTime}
          onChange={(e) => setStartTime(e.target.value)}
        />
      </div>

      <div>
        <label>End Time:</label>
        <input
          data-testid="end-time-input"
          type="datetime-local"
          value={endTime}
          onChange={(e) => setEndTime(e.target.value)}
        />
      </div>

      {cost > 0 && (
        <p data-testid="cost">Estimated Cost: ${cost.toFixed(2)}</p>
      )}

      {error && (
        <div data-testid="form-error" style={{ color: 'red' }}>{error}</div>
      )}

      <button type="submit" data-testid="book-btn">Book</button>
    </form>
  );
}

export default BookingForm;
